package com.lumix.risk.control;
import java.util.Objects;
/** P26 的 pure risk gate：輸入不可用、政策未生效或市場非正常時均 fail-closed。 */
public final class DeterministicRiskEvaluationPolicy { public RiskEvaluationResult evaluate(RiskPolicy policy, RiskEvaluationInput input) { policy=Objects.requireNonNull(policy,"policy"); input=Objects.requireNonNull(input,"input"); if(!input.evaluatedAt().isBefore(policy.effectiveAt()) && input.inputFreshness()!=RiskInputFreshness.FRESH) return result(RiskDecision.INPUT_NOT_TRUSTED_REJECTED,policy); if(input.evaluatedAt().isBefore(policy.effectiveAt()) || input.inputFreshness()!=RiskInputFreshness.FRESH) return result(RiskDecision.INPUT_NOT_TRUSTED_REJECTED,policy); if(input.marketState()!=RiskMarketState.NORMAL) return result(RiskDecision.MARKET_PROTECTION_REJECTED,policy); if(input.requestedAtomicAmount().compareTo(policy.maximumAtomicAmount())>0) return result(RiskDecision.LIMIT_EXCEEDED_REJECTED,policy); return result(RiskDecision.ALLOWED,policy); } private static RiskEvaluationResult result(RiskDecision d,RiskPolicy p){return new RiskEvaluationResult(d,p.version());} }
